import { createHash } from 'node:crypto'
import { DERIVED_RECIPES } from '@main/stats/derived/build'
import { buildGameTables, PLAYER_SUMS, TEAM_SUMS } from '@main/stats/derived/game'
import { buildSeasonTables } from '@main/stats/derived/season'
import { compileQuery } from '@main/stats/engine/compile'
import { LEAGUES } from '@shared/leagues'
import { CATALOGUE, metricIn } from '@shared/stats/catalogue'
import type { StatsQuery } from '@shared/stats/types'

/**
 * The NBA's and the WNBA's SQL, as hashes keyed by what produced them: every metric each league has,
 * alone, under three scopes (a season, per game by season, a date range at the game grain), a few
 * boards of many columns under the scopes the screens use, and the game and season table builds with
 * every source column present and with none. `tests/fixtures/nba-wnba-sql.json` holds the hashes the
 * code on `main` gave at T1302.5 (generated by running this same function there), so a change that
 * meant to touch only the college leagues proves it left these two byte for byte as they were.
 */
const hash = (text: string): string => createHash('sha1').update(text).digest('hex').slice(0, 16)

export async function sqlHashes(): Promise<Record<string, string>> {
  const out: Record<string, string> = {}
  for (const league of [LEAGUES.nba, LEAGUES.wnba]) {
    const season = league.id === 'nba' ? 2025 : 2024
    const ctx = { league, currentSeason: season + 1, priors: new Map<string, number>() }
    const text = (q: StatsQuery): string => {
      try {
        const c = compileQuery(q, ctx)
        return [c.sql, c.gamesSql, JSON.stringify(c.params), JSON.stringify(c.gamesParams)].join(
          '\n'
        )
      } catch (err) {
        return `refused: ${(err as Error).message}`
      }
    }
    const compiled = (key: string, q: StatsQuery): void => {
      out[key] = hash(text(q))
    }
    const scopes: [string, Partial<StatsQuery>][] = [
      ['season', {}],
      ['by season per game', { transform: 'perGame', groupBy: ['season'] }],
      ['dates', { scope: { seasons: [season], dates: [`${season - 1}-12-01`, `${season}-01-31`] } }]
    ]
    const available = CATALOGUE.filter((m) => !metricIn(m, league).unavailable)
    // One hash a metric, over its three scopes.
    for (const m of available) {
      out[`${league.id}|${m.id}`] = hash(
        scopes
          .map(([, extra]) =>
            text({
              entity: m.entity,
              metrics: [m.id],
              ...extra,
              scope: { seasons: [season], ...(extra.scope ?? {}) }
            })
          )
          .join('\n')
      )
    }
    const boards: [string, Partial<StatsQuery>][] = [
      ['totals', {}],
      ['per game', { transform: 'perGame' }],
      ['per 36', { transform: 'per36' }],
      ['per 100', { transform: 'per100' }],
      ['percentile', { transform: 'percentile' }],
      ['by opponent', { groupBy: ['opponent'] }],
      ['by month', { groupBy: ['month'] }],
      ['last 10', { scope: { seasons: [season], lastN: 10 } }],
      ['last 10 of the team', { scope: { seasons: [season], lastN: 10, lastNOf: 'team' } }],
      ['qualified', { transform: 'perGame', scope: { seasons: [season], qualifiedOnly: true } }],
      ['a team', { scope: { seasons: [season], teams: ['1610612738'] } }],
      ['a player', { scope: { seasons: [season], players: ['2544'] }, groupBy: ['game'] }],
      ['shrunk', { transform: 'perGame', shrunk: true }],
      ['playoffs', { scope: { seasons: [season], gameTypes: ['playoffs'] } }]
    ]
    const columns = {
      player: [
        'min',
        'pts',
        'reb',
        'ast',
        'stl',
        'blk',
        'tov',
        'fg_pct',
        'fg3_pct',
        'ft_pct',
        'fg3m'
      ],
      team: ['team_pts', 'opp_pts', 'team_ortg', 'team_drtg', 'team_pace', 'team_fg3m']
    }
    for (const entity of ['player', 'team'] as const) {
      for (const [name, extra] of boards) {
        compiled(`${league.id}|${entity} board|${name}`, {
          entity,
          metrics: columns[entity],
          ...extra,
          scope: { seasons: [season], ...(extra.scope ?? {}) }
        })
      }
    }
    // The builds, recorded through a stand-in database whose game tables hold the shared columns.
    const all = { has: () => true } as unknown as Set<string>
    const haves = {
      full: { tables: all, columns: { get: () => all } },
      none: { tables: new Set<string>(), columns: new Map<string, Set<string>>() }
    }
    for (const [name, have] of Object.entries(haves)) {
      const sqls: string[] = []
      const db = {
        exec: async (sql: string) => void sqls.push(sql),
        get: async () => ({ n: 0 }),
        all: async (_sql: string, params?: unknown[]) =>
          (params?.[0] === 'team_game' ? TEAM_SUMS : PLAYER_SUMS).map((c) => ({ c }))
      } as never
      await buildGameTables(db, have as never, DERIVED_RECIPES[league.derived], league)
      await buildSeasonTables(db)
      sqls.forEach((sql, i) => (out[`${league.id}|build ${name}|${i}`] = hash(sql)))
    }
  }
  return out
}
